'use client'

import type { ReactElement, ReactNode, RefObject } from 'react'
import { AlertDialog } from '@base-ui/react/alert-dialog'
import { Dialog } from '@base-ui/react/dialog'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Modal.module.css'

export interface ModalProps {
  /** The button that opens it. Omit when `open` is controlled from elsewhere. */
  trigger?: ReactElement
  /** Required: it names the dialog. */
  title: ReactNode
  description?: ReactNode
  children?: ReactNode
  /** Actions, right-aligned under the content: the main one last. */
  footer?: ReactNode
  /** Max width: 400px, 600px, 800px. Never wider than the screen. */
  size?: 'sm' | 'md' | 'lg'
  /** Defaults to `true`, or `false` when `isAlert`. */
  hasCloseButton?: boolean
  closeLabel?: string
  /**
   * A decision that must be made: `role="alertdialog"`, and a click on the
   * backdrop does not close it. Pair it with explicit buttons in `footer`.
   */
  isAlert?: boolean
  /** Close on a click on the backdrop. Ignored when `isAlert`. */
  closeOnBackdropClick?: boolean
  /**
   * While open, trap focus, lock page scroll and make the rest of the page
   * inert. `false` drops those three; the backdrop still covers the page.
   * Ignored when `isAlert`: an alert
   * is always modal.
   */
  isModal?: boolean
  /** Where the modal renders instead of `<body>`, e.g. an element in fullscreen. */
  container?: HTMLElement | null
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Where focus goes on open. By default, the first focusable element. */
  initialFocus?: RefObject<HTMLElement | null>
  className?: string
}

const widths = { sm: styles.sm, md: styles.md, lg: styles.lg }

export function Modal({
  trigger,
  title,
  description,
  children,
  footer,
  size = 'md',
  hasCloseButton,
  closeLabel = 'Close',
  isAlert = false,
  closeOnBackdropClick = true,
  isModal = true,
  container,
  open,
  defaultOpen,
  onOpenChange,
  initialFocus,
  className,
}: ModalProps) {
  const showClose = hasCloseButton ?? !isAlert
  const content = (
    <>
      {trigger && (isAlert ? <AlertDialog.Trigger render={trigger} /> : <Dialog.Trigger render={trigger} />)}
      <Dialog.Portal container={container}>
        <Dialog.Backdrop className={styles.backdrop} />
        <Dialog.Viewport className={styles.viewport}>
          <Dialog.Popup initialFocus={initialFocus} className={cn(styles.popup, widths[size], className)}>
            <div className={styles.header}>
              <div className={styles.heading}>
                <Dialog.Title className={styles.title}>{title}</Dialog.Title>
                {description && <Dialog.Description className={styles.description}>{description}</Dialog.Description>}
              </div>
              {showClose && (
                <Dialog.Close aria-label={closeLabel} className={styles.close}>
                  <Icon name="close" />
                </Dialog.Close>
              )}
            </div>
            {children && <div className={styles.body}>{children}</div>}
            {footer && <div className={styles.footer}>{footer}</div>}
          </Dialog.Popup>
        </Dialog.Viewport>
      </Dialog.Portal>
    </>
  )
  const change = onOpenChange && ((next: boolean) => onOpenChange(next))
  return isAlert ? (
    <AlertDialog.Root open={open} defaultOpen={defaultOpen} onOpenChange={change}>
      {content}
    </AlertDialog.Root>
  ) : (
    <Dialog.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={change}
      disablePointerDismissal={!closeOnBackdropClick}
      modal={isModal}
    >
      {content}
    </Dialog.Root>
  )
}

/** A button inside the modal that closes it, e.g. "Cancel": `<ModalClose render={<Button />}>Cancel</ModalClose>`. */
export const ModalClose = Dialog.Close

/* 50: the same layer as popups. Every overlay portals to the end of
   <body>, so at an equal z-index the one opened last is on top: a Select
   opened inside a modal shows above it, and the page behind stays under.
   Tooltips sit above all of them at 60. */
.backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay);
  background: var(--color-blanket);
  transition: opacity var(--duration-base);
}
.backdrop[data-starting-style],
.backdrop[data-ending-style] {
  opacity: 0;
}

/* Atlassian's modal keeps a 60px gutter to the screen on every side, and
   sits 60px from the top, not centred: a body that grows does not move the
   title. The spacing scale has no 60px step, so it is two steps added.
   The viewport is a size container, so the modal answers to the box it
   opens in: the screen, or a `container` narrower than it. */
.viewport {
  --modal-gutter: calc(var(--space-12) + var(--space-3));
  position: fixed;
  inset: 0;
  z-index: var(--layer-overlay);
  container-type: size;
  display: grid;
  place-items: start center;
  overflow-y: auto;
}

.popup {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  inline-size: calc(100% - 2 * var(--modal-gutter));
  max-block-size: calc(100cqb - 2 * var(--modal-gutter));
  margin-block: var(--modal-gutter);
  /* Atlassian's modal: content 24px from the edge. The padding gives back
     the border's pixel. */
  padding: calc(var(--space-container) - var(--border-width));
  border: var(--border-width) solid var(--color-border);
  border-radius: var(--radius-panel);
  background: var(--color-surface-overlay);
  box-shadow: var(--shadow-overlay);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  outline: none;
  transition:
    opacity var(--duration-base),
    scale var(--duration-base);
}
.popup[data-starting-style],
.popup[data-ending-style] {
  opacity: 0;
  scale: 0.97;
}

/* Atlassian's modal widths: 400, 600 and 800px. */
.sm {
  max-inline-size: 25rem;
}
.md {
  max-inline-size: 37.5rem;
}
.lg {
  max-inline-size: 50rem;
}

.header {
  display: flex;
  align-items: flex-start;
  gap: var(--space-group);
}

/* Title and description stacked, with the close button beside both.
   ConfirmDialog widens the gap to 16px through --modal-heading-gap. */
.heading {
  display: grid;
  flex: 1;
  gap: var(--modal-heading-gap, var(--space-inline));
  min-inline-size: 0;
}

.title {
  margin: 0;
  font-size: var(--text-heading-md);
  line-height: var(--leading-heading-md);
  font-family: var(--font-heading);
  font-weight: 600;
}

.description {
  margin: 0;
  color: var(--color-text-subtlest);
}

/* The body scrolls; title and footer stay in view. It takes the height
   left over, so on a full-screen modal the footer sits at the bottom. */
.body {
  flex: 1 1 auto;
  min-block-size: 0;
  /* A scroll container clips what overflows it, and a field's focus ring is
     drawn outside the field: pad by the ring and pull back by as much, so
     the content stays where it was and the ring shows whole. */
  padding: calc(var(--focus-width) + var(--focus-offset));
  /* 16px under the title, as Atlassian's modal header (24px around, 16px
     to the body). */
  margin: calc(var(--space-group) - var(--focus-width) - var(--focus-offset)) calc(-1 * (var(--focus-width) + var(--focus-offset)))
    calc(-1 * (var(--focus-width) + var(--focus-offset)));
  overflow-y: auto;
}

.footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--space-inline);
  /* Atlassian's modal footer: 16px above the buttons, 8px between them. */
  margin-block-start: var(--space-group);
}

.close {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  /* 4px around a 16px icon: a 24px box, the height of the title's line,
     flush with the padding. */
  padding: var(--control-xs-gap);
  margin: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text-subtlest);
  font-size: var(--icon-md);
  cursor: var(--cursor-button);
}
.close:hover {
  background: var(--color-background-neutral);
  color: var(--color-text);
}
.close:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset-inset);
}
@media (pointer: coarse) {
  .close::before {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: var(--target-coarse);
    block-size: var(--target-coarse);
    translate: -50% -50%;
  }
}

/* Under 480px Atlassian's modal is the whole screen: no gutter, no corner,
   no shadow. A 60px gutter either side would leave a phone a 240px column.
   Last in the file, so it wins over the widths above. */
@container (width < 30rem) {
  .popup {
    inline-size: 100%;
    max-inline-size: none;
    block-size: 100cqb;
    max-block-size: none;
    margin-block: 0;
    border-color: transparent;
    border-radius: 0;
    box-shadow: none;
  }
  /* Pinned to the bottom of the screen even with no body above it; the
     padding keeps the 16px the margin gave. */
  .footer {
    margin-block-start: auto;
    padding-block-start: var(--space-group);
  }
}
